import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.CfwCq2QB.js";const p=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/install.md","filePath":"en/guide/install.md"}'),n={name:"en/guide/install.md"};function i(l,e,s,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><h2 id="chrome-recommended" tabindex="-1">Chrome (recommended) <a class="header-anchor" href="#chrome-recommended" aria-label="Permalink to &quot;Chrome (recommended)&quot;">​</a></h2><p>Install from the <a href="https://chrome.google.com/webstore/detail/devgo/kcofdbjhicjdbmldlcffcijglkifnnjn" target="_blank" rel="noreferrer">Chrome Web Store</a> to get automatic updates.</p><p>After installing, click the puzzle icon in the toolbar and pin DevGo — then <code>Alt+1</code> (<code>⌥1</code> on macOS) opens the popup any time.</p><h2 id="edge-and-other-chromium-browsers" tabindex="-1">Edge and other Chromium browsers <a class="header-anchor" href="#edge-and-other-chromium-browsers" aria-label="Permalink to &quot;Edge and other Chromium browsers&quot;">​</a></h2><p>Install the Chrome Web Store build directly: open Edge&#39;s <code>Extensions → Manage extensions</code>, enable &quot;Allow extensions from other stores&quot; at the bottom left, then open the store link above and click Install.</p><h2 id="firefox" tabindex="-1">Firefox <a class="header-anchor" href="#firefox" aria-label="Permalink to &quot;Firefox&quot;">​</a></h2><p>Download the latest <code>dev-go-*.firefox.zip</code> from <a href="https://github.com/fedtop/DevGo/releases" target="_blank" rel="noreferrer">GitHub Releases</a>, unzip it, then:</p><ol><li>Open <code>about:debugging#/runtime/this-firefox</code></li><li>Click &quot;Load Temporary Add-on&quot; and pick <code>manifest.json</code> from the unzipped folder</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Firefox&#39;s temporary load disappears when the browser restarts — you&#39;d reload it each session. A permanent build needs the Mozilla store (AMO), which is on the roadmap. Also note that proxy switching doesn&#39;t work in Firefox yet — see the <a href="/dev-go-docs/en/faq/#proxy-switching-doesn-t-work-in-firefox">FAQ</a>.</p></div><h2 id="offline-install-chrome-when-the-store-is-unreachable" tabindex="-1">Offline install (Chrome, when the store is unreachable) <a class="header-anchor" href="#offline-install-chrome-when-the-store-is-unreachable" aria-label="Permalink to &quot;Offline install (Chrome, when the store is unreachable)&quot;">​</a></h2><ol><li>Download <code>dev-go-*-chrome.zip</code> from <a href="https://github.com/fedtop/DevGo/releases" target="_blank" rel="noreferrer">GitHub Releases</a> and unzip it</li><li>Open <code>chrome://extensions</code> and turn on &quot;Developer mode&quot; at the top right</li><li>Click &quot;Load unpacked&quot; and select the unzipped folder</li></ol><p>Offline installs don&#39;t auto-update: to upgrade, download the new build, replace the folder, and click &quot;Reload&quot; on DevGo&#39;s card in <code>chrome://extensions</code>.</p><h2 id="verify-it-works" tabindex="-1">Verify it works <a class="header-anchor" href="#verify-it-works" aria-label="Permalink to &quot;Verify it works&quot;">​</a></h2><p>Open any website: if <code>Alt+1</code> pops the DevGo panel and you can see the floating dock on the right edge of the page, you&#39;re set. Continue with the <a href="/dev-go-docs/en/guide/quick-start.html">Quick start</a>.</p>',15)])])}const u=o(n,[["render",i]]);export{p as __pageData,u as default};
